parts.text:
本地与本地缓存的 `origin/main` 一致。再跟**真实远端**核对一次 SHA，并列出远端树里的文件。

[tool-call run_code] {"code": "
const r = "C:\\Users\\jjq21\\Desktop\\github\\My-second-brain";
const q = JSON.stringify(r);
const cmd = [
 "'════ 真实远端 SHA（ls-remote）════'",
 "git -C " + q + " ls-remote origin main",
 "'════ 远端树里的 AI工具 文件 ════'",
 "git -C " + q + " ls-tree -r --name-only origin/main -- '50-知识/AI工具'",
 "'════ 计数 ════'",
 "'远端 AI工具 文件数: ' + (git -C " + q + " ls-tree -r --name-only origin/main -- '50-知识/AI工具' | Measure-Object).Count",
 "'远端总跟踪文件数: ' + (git -C " + q + " ls-tree -r --name-only origin/main | Measure-Object).Count",
].join("; ");
const res = await tools.pwsh({ command: cmd, description: "Verify true remote state and file list", timeoutMs: 180000 });
console.log(res.kind === "foreground" ? (res.stdout.text + res.stderr.text).slice(0, 5000) : JSON.stringify(res));
